// JsonQueryKind is the kind of a node: its rule, or its rule's labeled
// alternative, one JsonQueryKIND_ constant each. A labeled rule's own kind is for
// nodes with no alternative yet, which only an error-recovered tree has.
type JsonQueryKind uint16

// The kinds of nodes, numbered in rule order: a rule's own kind, then its
// labeled alternatives'.
const (
	JsonQueryKIND_query            JsonQueryKind = 0
	JsonQueryKIND_parenExp         JsonQueryKind = 1
	JsonQueryKIND_logicalExp       JsonQueryKind = 2
	JsonQueryKIND_presentExp       JsonQueryKind = 3
	JsonQueryKIND_compareExp       JsonQueryKind = 4
	JsonQueryKIND_attrPath         JsonQueryKind = 5
	JsonQueryKIND_subAttr          JsonQueryKind = 6
	JsonQueryKIND_value            JsonQueryKind = 7
	JsonQueryKIND_boolean          JsonQueryKind = 8
	JsonQueryKIND_null             JsonQueryKind = 9
	JsonQueryKIND_version          JsonQueryKind = 10
	JsonQueryKIND_string           JsonQueryKind = 11
	JsonQueryKIND_double           JsonQueryKind = 12
	JsonQueryKIND_long             JsonQueryKind = 13
	JsonQueryKIND_listOfInts       JsonQueryKind = 14
	JsonQueryKIND_listOfDoubles    JsonQueryKind = 15
	JsonQueryKIND_listOfStrings    JsonQueryKind = 16
	JsonQueryKIND_listStrings      JsonQueryKind = 17
	JsonQueryKIND_subListOfStrings JsonQueryKind = 18
	JsonQueryKIND_listDoubles      JsonQueryKind = 19
	JsonQueryKIND_subListOfDoubles JsonQueryKind = 20
	JsonQueryKIND_listInts         JsonQueryKind = 21
	JsonQueryKIND_subListOfInts    JsonQueryKind = 22
)

// jsonQueryGalopKindBase is each rule's own kind; its labeled alternatives' kinds follow.
var jsonQueryGalopKindBase = [...]JsonQueryKind{0, 5, 6, 7, 17, 18, 19, 20, 21, 22}

// Kind is n's kind. Switching on it costs a table lookup and builds nothing:
//
//	switch p := n.Parent(); p.Kind() {
//	case JsonQueryKIND_primary: c := PrimaryNode{p}; ...
//	}
func (n JsonQueryNodeRef) Kind() JsonQueryKind {
	d := &n.t.Nodes[n.i]
	return jsonQueryGalopKindBase[d.Rule] + JsonQueryKind(d.Alt)
}

// JsonQueryHandle is a node as a handle type (see Typed). Its name ends in Handle,
// never Node, so no rule's or label's handle type can take it. Every handle
// type's pointer is one, so a type switch over them reads like one over
// ANTLR's context types:
//
//	switch c := n.Parent().Typed().(type) {
//	case *PrimaryNode: ...
//	}
type JsonQueryHandle interface {
	// Ref is the node itself.
	Ref() JsonQueryNodeRef
}

// Ref is n itself, so that every handle type is an JsonQueryHandle.
func (n JsonQueryNodeRef) Ref() JsonQueryNodeRef { return n }

// Typed is n as a pointer to its most specific handle: its labeled
// alternative's when it has one, its rule's otherwise; nil for no node. The
// pointer is into the tree's handles, built on the first call, once, safely
// from any goroutine (16 bytes a node); after that Typed allocates nothing.
// The handle is shared: do not write through the pointer. A switch on Kind
// needs no handles at all.
func (n JsonQueryNodeRef) Typed() JsonQueryHandle {
	if !n.Ok() {
		return nil
	}
	h := &n.t.handles()[n.i]
	switch n.Kind() {
	case JsonQueryKIND_query:
		return (*QueryNode)(h)
	case JsonQueryKIND_parenExp:
		return (*ParenExpNode)(h)
	case JsonQueryKIND_logicalExp:
		return (*LogicalExpNode)(h)
	case JsonQueryKIND_presentExp:
		return (*PresentExpNode)(h)
	case JsonQueryKIND_compareExp:
		return (*CompareExpNode)(h)
	case JsonQueryKIND_attrPath:
		return (*AttrPathNode)(h)
	case JsonQueryKIND_subAttr:
		return (*SubAttrNode)(h)
	case JsonQueryKIND_value:
		return (*ValueNode)(h)
	case JsonQueryKIND_boolean:
		return (*BooleanNode)(h)
	case JsonQueryKIND_null:
		return (*NullNode)(h)
	case JsonQueryKIND_version:
		return (*VersionNode)(h)
	case JsonQueryKIND_string:
		return (*StringNode)(h)
	case JsonQueryKIND_double:
		return (*DoubleNode)(h)
	case JsonQueryKIND_long:
		return (*LongNode)(h)
	case JsonQueryKIND_listOfInts:
		return (*ListOfIntsNode)(h)
	case JsonQueryKIND_listOfDoubles:
		return (*ListOfDoublesNode)(h)
	case JsonQueryKIND_listOfStrings:
		return (*ListOfStringsNode)(h)
	case JsonQueryKIND_listStrings:
		return (*ListStringsNode)(h)
	case JsonQueryKIND_subListOfStrings:
		return (*SubListOfStringsNode)(h)
	case JsonQueryKIND_listDoubles:
		return (*ListDoublesNode)(h)
	case JsonQueryKIND_subListOfDoubles:
		return (*SubListOfDoublesNode)(h)
	case JsonQueryKIND_listInts:
		return (*ListIntsNode)(h)
	case JsonQueryKIND_subListOfInts:
		return (*SubListOfIntsNode)(h)
	}
	return n
}

// handles is t's nodes as handles, built on first use. Every handle type has
// the same underlying type as an element, so a pointer to one converts to a
// pointer to any handle type.
func (t *JsonQueryTree) handles() []struct{ JsonQueryNodeRef } {
	t.typedOnce.Do(func() {
		hs := make([]struct{ JsonQueryNodeRef }, len(t.Nodes))
		for i := range hs {
			hs[i].JsonQueryNodeRef = JsonQueryNodeRef{t, int32(i)}
		}
		t.typed = hs
	})
	return t.typed
}

// JsonQueryListener is told about a tree's nodes as JsonQueryWalk passes them, as
// ANTLR's listener is: Enter and Exit per rule and labeled alternative, the
// EveryRule pair around every node, and each token and error token (see
// JsonQueryTree). Embed JsonQueryBaseListener to start from no-ops.
type JsonQueryListener interface {
	EnterEveryRule(n JsonQueryNodeRef)
	ExitEveryRule(n JsonQueryNodeRef)
	VisitTerminal(t JsonQueryTerminal)
	VisitErrorNode(t JsonQueryTerminal)
	EnterParenExp(n ParenExpNode)
	ExitParenExp(n ParenExpNode)
	EnterLogicalExp(n LogicalExpNode)
	ExitLogicalExp(n LogicalExpNode)
	EnterPresentExp(n PresentExpNode)
	ExitPresentExp(n PresentExpNode)
	EnterCompareExp(n CompareExpNode)
	ExitCompareExp(n CompareExpNode)
	EnterAttrPath(n AttrPathNode)
	ExitAttrPath(n AttrPathNode)
	EnterSubAttr(n SubAttrNode)
	ExitSubAttr(n SubAttrNode)
	EnterBoolean(n BooleanNode)
	ExitBoolean(n BooleanNode)
	EnterNull(n NullNode)
	ExitNull(n NullNode)
	EnterVersion(n VersionNode)
	ExitVersion(n VersionNode)
	EnterString(n StringNode)
	ExitString(n StringNode)
	EnterDouble(n DoubleNode)
	ExitDouble(n DoubleNode)
	EnterLong(n LongNode)
	ExitLong(n LongNode)
	EnterListOfInts(n ListOfIntsNode)
	ExitListOfInts(n ListOfIntsNode)
	EnterListOfDoubles(n ListOfDoublesNode)
	ExitListOfDoubles(n ListOfDoublesNode)
	EnterListOfStrings(n ListOfStringsNode)
	ExitListOfStrings(n ListOfStringsNode)
	EnterListStrings(n ListStringsNode)
	ExitListStrings(n ListStringsNode)
	EnterSubListOfStrings(n SubListOfStringsNode)
	ExitSubListOfStrings(n SubListOfStringsNode)
	EnterListDoubles(n ListDoublesNode)
	ExitListDoubles(n ListDoublesNode)
	EnterSubListOfDoubles(n SubListOfDoublesNode)
	ExitSubListOfDoubles(n SubListOfDoublesNode)
	EnterListInts(n ListIntsNode)
	ExitListInts(n ListIntsNode)
	EnterSubListOfInts(n SubListOfIntsNode)
	ExitSubListOfInts(n SubListOfIntsNode)
}

