// JsonQueryWalk walks n's subtree depth first, as ANTLR's ParseTreeWalker does:
// at each node EnterEveryRule and the node's Enter method, then its children
// in order (VisitTerminal for a token, VisitErrorNode for an error token),
// then its Exit method and ExitEveryRule. It keeps its own stack, so a deep
// tree cannot overflow Go's.
func JsonQueryWalk(n JsonQueryNodeRef, l JsonQueryListener) {
	if !n.Ok() {
		return
	}
	type frame struct {
		n    JsonQueryNodeRef
		next int
	}
	stack := []frame{{n, -1}}
	for len(stack) > 0 {
		f := &stack[len(stack)-1]
		if f.next < 0 {
			l.EnterEveryRule(f.n)
			JsonQueryGalopEnter(l, f.n)
			f.next = 0
		}
		if f.next < f.n.ChildCount() {
			c := f.n.Child(f.next)
			f.next++
			switch {
			case c.IsError():
				l.VisitErrorNode(c.Terminal())
			case c.IsToken():
				l.VisitTerminal(c.Terminal())
			default:
				stack = append(stack, frame{c.Node(), -1})
			}
			continue
		}
		JsonQueryGalopExit(l, f.n)
		l.ExitEveryRule(f.n)
		stack = stack[:len(stack)-1]
	}
}

// JsonQueryGalopEnter calls l's Enter method for n's kind.
func JsonQueryGalopEnter(l JsonQueryListener, n JsonQueryNodeRef) {
	switch n.Kind() {
	case JsonQueryKIND_parenExp:
		l.EnterParenExp(ParenExpNode{n})
	case JsonQueryKIND_logicalExp:
		l.EnterLogicalExp(LogicalExpNode{n})
	case JsonQueryKIND_presentExp:
		l.EnterPresentExp(PresentExpNode{n})
	case JsonQueryKIND_compareExp:
		l.EnterCompareExp(CompareExpNode{n})
	case JsonQueryKIND_attrPath:
		l.EnterAttrPath(AttrPathNode{n})
	case JsonQueryKIND_subAttr:
		l.EnterSubAttr(SubAttrNode{n})
	case JsonQueryKIND_boolean:
		l.EnterBoolean(BooleanNode{n})
	case JsonQueryKIND_null:
		l.EnterNull(NullNode{n})
	case JsonQueryKIND_version:
		l.EnterVersion(VersionNode{n})
	case JsonQueryKIND_string:
		l.EnterString(StringNode{n})
	case JsonQueryKIND_double:
		l.EnterDouble(DoubleNode{n})
	case JsonQueryKIND_long:
		l.EnterLong(LongNode{n})
	case JsonQueryKIND_listOfInts:
		l.EnterListOfInts(ListOfIntsNode{n})
	case JsonQueryKIND_listOfDoubles:
		l.EnterListOfDoubles(ListOfDoublesNode{n})
	case JsonQueryKIND_listOfStrings:
		l.EnterListOfStrings(ListOfStringsNode{n})
	case JsonQueryKIND_listStrings:
		l.EnterListStrings(ListStringsNode{n})
	case JsonQueryKIND_subListOfStrings:
		l.EnterSubListOfStrings(SubListOfStringsNode{n})
	case JsonQueryKIND_listDoubles:
		l.EnterListDoubles(ListDoublesNode{n})
	case JsonQueryKIND_subListOfDoubles:
		l.EnterSubListOfDoubles(SubListOfDoublesNode{n})
	case JsonQueryKIND_listInts:
		l.EnterListInts(ListIntsNode{n})
	case JsonQueryKIND_subListOfInts:
		l.EnterSubListOfInts(SubListOfIntsNode{n})
	}
}

// JsonQueryGalopExit calls l's Exit method for n's kind.
func JsonQueryGalopExit(l JsonQueryListener, n JsonQueryNodeRef) {
	switch n.Kind() {
	case JsonQueryKIND_parenExp:
		l.ExitParenExp(ParenExpNode{n})
	case JsonQueryKIND_logicalExp:
		l.ExitLogicalExp(LogicalExpNode{n})
	case JsonQueryKIND_presentExp:
		l.ExitPresentExp(PresentExpNode{n})
	case JsonQueryKIND_compareExp:
		l.ExitCompareExp(CompareExpNode{n})
	case JsonQueryKIND_attrPath:
		l.ExitAttrPath(AttrPathNode{n})
	case JsonQueryKIND_subAttr:
		l.ExitSubAttr(SubAttrNode{n})
	case JsonQueryKIND_boolean:
		l.ExitBoolean(BooleanNode{n})
	case JsonQueryKIND_null:
		l.ExitNull(NullNode{n})
	case JsonQueryKIND_version:
		l.ExitVersion(VersionNode{n})
	case JsonQueryKIND_string:
		l.ExitString(StringNode{n})
	case JsonQueryKIND_double:
		l.ExitDouble(DoubleNode{n})
	case JsonQueryKIND_long:
		l.ExitLong(LongNode{n})
	case JsonQueryKIND_listOfInts:
		l.ExitListOfInts(ListOfIntsNode{n})
	case JsonQueryKIND_listOfDoubles:
		l.ExitListOfDoubles(ListOfDoublesNode{n})
	case JsonQueryKIND_listOfStrings:
		l.ExitListOfStrings(ListOfStringsNode{n})
	case JsonQueryKIND_listStrings:
		l.ExitListStrings(ListStringsNode{n})
	case JsonQueryKIND_subListOfStrings:
		l.ExitSubListOfStrings(SubListOfStringsNode{n})
	case JsonQueryKIND_listDoubles:
		l.ExitListDoubles(ListDoublesNode{n})
	case JsonQueryKIND_subListOfDoubles:
		l.ExitSubListOfDoubles(SubListOfDoublesNode{n})
	case JsonQueryKIND_listInts:
		l.ExitListInts(ListIntsNode{n})
	case JsonQueryKIND_subListOfInts:
		l.ExitSubListOfInts(SubListOfIntsNode{n})
	}
}

// ParseQuery parses the tokens of ts as query, from the first token, and
// returns the tree's root. On a syntax error it returns the error and no tree.
// The parse stops after the input query matches; Tree().Next is the index of
