// JsonQueryParseError is a syntax error a recovering parse reports, as ANTLR's
// default error strategy reports it, with what code that explains an error
// reads of ANTLR's parser when the error is reported.
type JsonQueryParseError struct {
	JsonQuerySyntaxError
	// Token is the index in Tokens of the offending token; -1, as Node, for
	// the error of tokens that do not end with EOF.
	Token int
	// Node is the node of the rule being parsed (ANTLR's
	// GetParserRuleContext()), and Kids the number of children it had
	// then. Where ANTLR replaced that rule's context to enter a labeled
	// alternative, Node is the replacement's.
	Node int32
	Kids int
	// Read is the index of the furthest token ANTLR's parse had read when
	// it reported the error: the current token, and the tokens past it that
	// prediction or single-token deletion looked at. ANTLR's token stream
	// lexes as it is read, so it reports the token recognition errors of
	// tokens up to Read (Tokens.ErrorAt) before this error.
	Read int
	// Expected are the token types ANTLR's GetExpectedTokens() gives when
	// the error is reported, as an error listener sees them: what can
	// follow the parser's state through the rules being parsed, in
	// ascending order, JsonQueryEOF first. It is empty for the error of tokens
	// that do not end with EOF.
	Expected []int32
}

// JsonQueryParseWithRecovery parses the tokens of ts as the rule with index rule
// (an JsonQueryRULE_ constant), as the rule's Parse function does, and recovers
// from syntax errors as ANTLR's default error strategy does. Without a
// syntax error it returns the Parse function's tree and no errors. Otherwise
// it returns the tree ANTLR's parser builds while it recovers, as galop's
// converter converts it, with its error tokens (see JsonQueryTree), and every
// syntax error ANTLR reports, in order. The root is missing (its Ok is
// false) only when the tokens do not end with EOF or there is no such rule.
func JsonQueryParseWithRecovery(ts *JsonQueryTokens, rule int) (JsonQueryNodeRef, []JsonQueryParseError) {
	if rule < 0 || rule >= len(JsonQueryGalopRuleFuncs) {
		return JsonQueryNodeRef{}, []JsonQueryParseError{{JsonQuerySyntaxError: JsonQuerySyntaxError{Msg: "no rule with index " + strconv.Itoa(rule)}, Token: -1, Node: -1}}
	}
	if err := JsonQueryGalopNoEOF(ts); err != nil {
		return JsonQueryNodeRef{}, []JsonQueryParseError{{JsonQuerySyntaxError: *err, Token: -1, Node: -1}}
	}
	p := newJsonQueryGalopParser(ts)
	p.keepErr = true
	t, root, err := p.run(JsonQueryGalopRuleFuncs[rule], JsonQueryGalopRuleStartState[rule], JsonQueryGalopRuleRepairs[rule])
	if err != nil {
		rt, rroot, errs := p.recoverParse(rule)
		if len(errs) > 0 {
			return JsonQueryNodeRef{rt, rroot}, errs
		}
		// ANTLR reports no error: its prediction fell back on an alternative
		// where the parse's prediction failed (see deadEnd). The Parse function's
		// run takes those, and its tree is the one to return.
		if t, root, err = newJsonQueryGalopParser(ts).run(JsonQueryGalopRuleFuncs[rule], JsonQueryGalopRuleStartState[rule], JsonQueryGalopRuleRepairs[rule]); err != nil {
			return JsonQueryNodeRef{rt, rroot}, errs
		}
	}
	switch {
	case len(ts.ErrorAt) > 0 && int(ts.ErrorAt[len(ts.ErrorAt)-1]) <= t.Next:
		// ANTLR reads at least to Next, so it reports every token
		// recognition error.
		t.Read = t.Next
	case len(ts.Errors) > 0:
		// Where ANTLR's parse stops reading decides which of them it
		// reports, so the replay runs for Read alone (on a parser of its
		// own: the replay reuses its parser's tree).
		r, _, _ := newJsonQueryGalopParser(ts).recoverParse(rule)
		t.Read = r.Read
	default:
		t.Read = -1
	}
	return JsonQueryNodeRef{t, root}, nil
}

// recoverParse parses from the first token with ANTLR's error recovery; see
// recoverySource. It predicts in LL mode over the tokens alone, as
// antlrError's replay does, but runs every full-context prediction again
// rather than reuse a repair's recorded answers, so that peek sees how far
// each one reads.
func (p *JsonQueryGalopParser) recoverParse(rule int) (*JsonQueryTree, int32, []JsonQueryParseError) {
	p.ll, p.group, p.peek = true, false, 0
	// The failed parse's tree is dropped; its arrays are reused.
	t := p.tree
	t.Nodes, t.Kids, t.TokenLabels = t.Nodes[:0], t.Kids[:0], t.TokenLabels[:0]
	r := &JsonQueryGalopRecovery{
		e:         JsonQueryGalopEmu{p: p},
		tree:      t,
		last:      -1,
		lastIndex: -1,
	}
	root := r.parse(rule)
	r.tree.Next = p.pos
	r.tree.FindDropped()
	r.tree.Read = r.read()
	errs := make([]JsonQueryParseError, len(r.errs))
	for i, x := range r.errs {
		tok := p.ts.Tokens[x.err.at]
		errs[i] = JsonQueryParseError{
			JsonQuerySyntaxError: JsonQuerySyntaxError{Line: int(tok.Line), Column: int(tok.Column), Msg: x.err.msg},
			Token:                x.err.at,
			Node:                 r.nodeOf[x.frame],
			Kids:                 x.kids,
			Read:                 x.read,
			Expected:             x.expected,
		}
	}
	return r.tree, root, errs
}

// JsonQueryGalopRecovery is the state of a recovering parse: ANTLR's parser state
// (GetState, the error strategy's fields), the rules being parsed and the
// tree being built.
type JsonQueryGalopRecovery struct {
	e JsonQueryGalopEmu
	// frames are the rules being parsed, innermost last; the parser's stack
	// holds their return states, as in the replay.
	frames []JsonQueryGalopRecFrame
	// kids are the children of the rules being parsed, as in the native
	// parser; errPos the positions in kids of error tokens; labs the label
	// assignments of the rules being parsed.
	kids   []int32
	errPos []int
	labs   []JsonQueryGalopRecLabel
	tree   *JsonQueryTree
	// last is the last real token added to the tree, -1 for none: a
	// conjured token sits at the start of the token after it.
	last int32
	// state is ANTLR's GetState(): the ATN state of the generated code's
	// last SetState.
	state int32
	// The default error strategy's errorRecoveryMode, lastErrorIndex and
	// lastErrorStates.
	recovering bool
	lastIndex  int
	lastStates []int32
	// errs are the errors reported; nodeOf maps a frame's serial number to
	// its node, once the rule is done.
	errs   []JsonQueryGalopRecError
	nodeOf []int32
	// aligner aligns the children of nodes whose labels ANTLR keeps only
	// the last match of (see labelNode).
	aligner JsonQueryGalopAligner
}

// JsonQueryGalopRecFrame is a rule being parsed: ANTLR's context for it.
type JsonQueryGalopRecFrame struct {
	rule int32
	// invoking is the state that called the rule (ANTLR's invokingState),
	// -1 for the entry rule.
	invoking int32
	// start is the rule's first token; kids, errs and labs where its
	// children, error tokens and label assignments start; last the tree's
	// last real token when the rule started.
	start, kids, errs, labs int
	last                    int32
	serial                  int32
	alt                     uint8
	// exc says the rule recovered from an error (ANTLR's exception field).
	exc bool
}

// JsonQueryGalopRecLabel is one assignment to a label field of a rule being parsed:
// label (JsonQueryGalopStateLabel's encoding) gets node, or token tok when node < 0
// (-1 for none, as ANTLR stores nil).
type JsonQueryGalopRecLabel struct {
	label     uint16
	node, tok int32
}

// JsonQueryGalopRecError is a reported error with the frame it was reported in, that
// frame's number of children then, and the tokens expected then.
type JsonQueryGalopRecError struct {
	err      JsonQueryGalopEmuError
	frame    int32
	kids     int
	read     int
	expected []int32
}

// enter starts rule, called from state invoking: ANTLR's EnterRule, which
// starts the rule's context at the current token. A rule with one labeled
// alternative enters it at once.
func (r *JsonQueryGalopRecovery) enter(rule, invoking int32) {
	serial := int32(len(r.nodeOf))
	r.nodeOf = append(r.nodeOf, -1)
	r.frames = append(r.frames, JsonQueryGalopRecFrame{
		rule: rule, invoking: invoking, start: r.e.p.pos,
		kids: len(r.kids), errs: len(r.errPos), labs: len(r.labs), last: r.last,
		serial: serial, alt: JsonQueryGalopRuleAlt[rule],
	})
}

// enterOuterAlt makes the rule being parsed the labeled alternative alt:
// ANTLR replaces the rule's context with the alternative's, which keeps none
// of its children.
func (r *JsonQueryGalopRecovery) enterOuterAlt(alt uint8) {
	f := &r.frames[len(r.frames)-1]
	f.alt = alt
	r.kids = r.kids[:f.kids]
	r.errPos = r.errPos[:f.errs]
	r.last = f.last
}

// exit ends the rule being parsed: ANTLR's ExitRule. It adds the rule's node
// and returns the state its caller goes on at, or the node when the rule is
// the entry rule (and -1 otherwise).
func (r *JsonQueryGalopRecovery) exit() (int32, int32) {
	p := r.e.p
	f := r.frames[len(r.frames)-1]
	r.frames = r.frames[:len(r.frames)-1]
	id := r.finish(f)
	if len(r.frames) == 0 {
		return -1, id
	}
	r.kids = append(r.kids, id)
	if l := JsonQueryGalopStateLabel[f.invoking]; l != 0 {
		r.labs = append(r.labs, JsonQueryGalopRecLabel{l, id, -1})
	}
	r.state = f.invoking
	follow := p.stack[len(p.stack)-1]
	p.stack = p.stack[:len(p.stack)-1]
	return follow, -1
}

// finish adds the node of frame f, which ends at the token before the
// current one, with its children and labels.
func (r *JsonQueryGalopRecovery) finish(f JsonQueryGalopRecFrame) int32 {
	t := r.tree
	off := len(t.Kids)
	t.Kids = append(t.Kids, r.kids[f.kids:]...)
	for _, k := range r.errPos[f.errs:] {
		t.ErrorKids = append(t.ErrorKids, int32(off+k-f.kids))
	}
	r.errPos = r.errPos[:f.errs]
	r.kids = r.kids[:f.kids]
	t.Nodes = append(t.Nodes, JsonQueryNodeData{Rule: uint16(f.rule), Alt: f.alt, Kids: int32(off), NKids: int32(len(t.Kids) - off), Start: int32(f.start), Stop: int32(r.e.p.pos - 1)})
	id := int32(len(t.Nodes) - 1)
	r.labelNode(f, id)
	r.labs = r.labs[:f.labs]
	r.nodeOf[f.serial] = id
	return id
}

// recursionStart starts an iteration of a left-recursive rule's loop with
// op alternative alt, as ANTLR's PushNewRecursionContext does: the rule's
// node so far is finished and becomes the first child of a new one, which
// starts where it did, has no exception, and stores it in label left (if
// not 0).
func (r *JsonQueryGalopRecovery) recursionStart(alt uint8, left uint16) {
	f := &r.frames[len(r.frames)-1]
	id := r.finish(*f)
	r.kids = append(r.kids, id)
	if left != 0 {
		r.labs = append(r.labs, JsonQueryGalopRecLabel{left, id, -1})
	}
	f.serial = int32(len(r.nodeOf))
	r.nodeOf = append(r.nodeOf, -1)
	f.alt, f.exc, f.last = alt, false, r.last
}

// labelNode records the labels of node id, of frame f, as galop's converter
// records them from ANTLR's label fields: a list label every node or token
// assigned to it, another label the last one; tokens ANTLR's recovery made
// up are left out.
func (r *JsonQueryGalopRecovery) labelNode(f JsonQueryGalopRecFrame, id int32) {
	// Where a label field holds only a label's last match, the converter
	// first aligns the children of a node ANTLR did not recover in.
	if len(JsonQueryGalopAlignKinds) > 0 && !f.exc {
		if nfa := JsonQueryGalopAlignKinds[uint32(f.rule)<<8|uint32(f.alt)]; nfa != nil && r.align(nfa, id) {
			return
		}
	}
	labs := r.labs[f.labs:]
	if len(labs) == 0 {
		return
	}
	t := r.tree
	first := len(t.TokenLabels)
	var seen [JsonQueryGalopLabelList]bool
	for i := len(labs) - 1; i >= 0; i-- {
		l := labs[i]
		num := uint8(l.label & JsonQueryGalopLabelNumber)
		if l.label&JsonQueryGalopLabelList == 0 {
			if seen[num] {
				continue
			}
			seen[num] = true
		}
		switch {
		case l.node >= 0:
			t.Nodes[l.node].Label = num
		case l.tok >= 0 && int(l.tok) < len(t.Tokens):
			t.TokenLabels = append(t.TokenLabels, JsonQueryTokenLabel{Node: id, Token: l.tok, Label: num})
		}
	}
	// The labels were found last first; the converter lists them by token.
	slices.Reverse(t.TokenLabels[first:])
	slices.SortStableFunc(t.TokenLabels[first:], func(a, b JsonQueryTokenLabel) int { return int(a.Token - b.Token) })
}

// label records that the match at state s stored tok in its label, if any.
func (r *JsonQueryGalopRecovery) label(s int32, tok int32) {
	if l := JsonQueryGalopStateLabel[s]; l != 0 {
		r.labs = append(r.labs, JsonQueryGalopRecLabel{l, -1, tok})
	}
}

// take adds the current token to the rule being parsed, as an error token
// when isErr, and moves past it (not past EOF); it returns the token.
func (r *JsonQueryGalopRecovery) take(isErr bool) int32 {
	p := r.e.p
	i := p.pos
	if isErr {
		r.errPos = append(r.errPos, len(r.kids))
	}
	r.kids = append(r.kids, int32(-i-1))
	r.last = int32(i)
	if p.types[i] != JsonQueryEOF {
		p.pos++
	}
	return int32(i)
}

// report reports err, unless the parser is in error recovery mode, and
// enters that mode, as ANTLR's ReportError, ReportUnwantedToken and
// ReportMissingToken do.
func (r *JsonQueryGalopRecovery) report(err *JsonQueryGalopEmuError) {
	if r.recovering {
		return
	}
	r.recovering = true
	f := r.frames[len(r.frames)-1]
	// An error listener asks the parser at its state, in the rules being parsed.
	exp := r.e.expected(r.state).types()
	r.errs = append(r.errs, JsonQueryGalopRecError{*err, f.serial, len(r.kids) - f.kids, r.read(), exp})
}

// missing is single-token insertion's result: the token conjure adds when
// add is set (ANTLR's Match adds the token it makes up), otherwise -1, as
// the converter leaves out a made-up token that is not in the tree.
func (r *JsonQueryGalopRecovery) missing(exp *JsonQueryGalopExpected, add bool) int32 {
	if !add {
		return -1
	}
	return r.conjure(exp)
}

// pend leaves err pending, as ANTLR's SetError does, until an error check
// reports it (see reportPending).
func (r *JsonQueryGalopRecovery) pend(err *JsonQueryGalopEmuError) { r.e.pending = err }

// reportPending reports the pending error at a rule's error exit, where
// ANTLR's generated code first sets the rule's exception field.
func (r *JsonQueryGalopRecovery) reportPending(err *JsonQueryGalopEmuError) {
	r.frames[len(r.frames)-1].exc = true
	r.report(err)
}

// conjure adds the token ANTLR's GetMissingSymbol makes up, the first type
// of exp, as an error token of the rule being parsed, and returns it.
func (r *JsonQueryGalopRecovery) conjure(exp *JsonQueryGalopExpected) int32 {
	p := r.e.p
	t := r.tree
	typ := exp.first()
	var text string
	switch {
	case typ == JsonQueryEOF:
		text = "<missing EOF>"
	case typ > 0 && int(typ) < len(JsonQueryGalopLiteralNames):
		text = "<missing " + JsonQueryGalopLiteralNames[typ] + ">"
	default:
		text = "<missing undefined>"
	}
	at := p.ts.Tokens[p.pos]
	if at.Type == JsonQueryEOF && p.pos > 0 {
		at = p.ts.Tokens[p.pos-1]
	}
	pos := t.Tokens[min(int(r.last)+1, len(t.Tokens)-1)].Start
	t.Conjured = append(t.Conjured, JsonQueryToken{Type: typ, Start: pos, End: pos, Line: at.Line, Column: at.Column})
	t.ConjuredText = append(t.ConjuredText, text)
	ref := int32(len(t.Tokens) + len(t.Conjured) - 1)
	r.errPos = append(r.errPos, len(r.kids))
	r.kids = append(r.kids, -ref-1)
	return ref
}

// align records the labels of node id as galop's converter's align does:
// along the first path through nfa that matches the node's children, trying
// each state's edges in ANTLR's order. It reports false, recording nothing,
// when the node has an error token or the children do not match.
func (r *JsonQueryGalopRecovery) align(nfa *JsonQueryGalopAlignNFA, id int32) bool {
	t := r.tree
	n := t.Nodes[id]
	if k := len(t.ErrorKids); k > 0 && t.ErrorKids[k-1] >= n.Kids {
		return false
	}
	a := &r.aligner
	a.nfa, a.kids = nfa, t.Kids[n.Kids:n.Kids+n.NKids]
	size := len(nfa.edges) * (len(a.kids) + 1)
	a.failed = slices.Grow(a.failed[:0], size)[:size]
	clear(a.failed)
	a.labels = slices.Grow(a.labels[:0], len(a.kids))[:len(a.kids)]
	if !a.path(t, 0, 0) {
		return false
	}
	first := len(t.TokenLabels)
	for j, label := range a.labels {
		switch k := a.kids[j]; {
		case label == 0:
		case k >= 0:
			t.Nodes[k].Label = label
		default:
			t.TokenLabels = append(t.TokenLabels, JsonQueryTokenLabel{Node: id, Token: -k - 1, Label: label})
		}
	}
	slices.SortStableFunc(t.TokenLabels[first:], func(a, b JsonQueryTokenLabel) int { return int(a.Token - b.Token) })
	return true
}

// JsonQueryGalopAligner is align's state, kept between nodes.
type JsonQueryGalopAligner struct {
	nfa    *JsonQueryGalopAlignNFA
	kids   []int32
	labels []uint8
	failed []bool
}

// path reports whether the automaton gets from state s at child pos to its
// accepting state after the last child, noting each child's label.
func (a *JsonQueryGalopAligner) path(t *JsonQueryTree, s int32, pos int) bool {
	if s == a.nfa.accept && pos == len(a.kids) {
		return true
	}
	key := int(s)*(len(a.kids)+1) + pos
	if a.failed[key] {
		return false
	}
	a.failed[key] = true
	for i := range a.nfa.edges[s] {
		e := &a.nfa.edges[s][i]
		if e.op == JsonQueryGalopAlignOpEps {
			if a.path(t, e.to, pos) {
				return true
			}
		} else if pos < len(a.kids) && e.matches(t, a.kids[pos]) {
			a.labels[pos] = e.label
			if a.path(t, e.to, pos+1) {
				return true
			}
		}
	}
	return false
}

// matches reports whether child k is what edge e matches.
func (e *JsonQueryGalopAlignEdge) matches(t *JsonQueryTree, k int32) bool {
	if e.op == JsonQueryGalopAlignOpRule {
		return k >= 0 && int32(t.Nodes[k].Rule) == e.sym
	}
	if k >= 0 {
		return false
	}
	ty := t.Token(int(-k - 1)).Type
	if e.op == JsonQueryGalopAlignOpToken {
		return ty == e.sym
	}
	for i := 0; i+1 < len(e.set); i += 2 {
		if e.set[i] <= ty && ty <= e.set[i+1] {
			return true
		}
	}
	return false
}

// JsonQueryGalopAlignStep is one step of an alternative, as generated: a token, a token set
// (set holds lo, hi pairs), a rule (sym), a choice among alts (exit says where
// the alternative that matches nothing is tried: -1 none, 0 first, 1 last) or
// a loop over alts[0] (plus: once before deciding; cont: continuing is tried
// before leaving). label is the label it stores under, or 0.
type JsonQueryGalopAlignStep struct {
	op    uint8
	sym   int32
	label uint8
	set   []int32
	alts  [][]JsonQueryGalopAlignStep
	exit  int8
	plus  bool
	cont  bool
}

// The kinds of JsonQueryGalopAlignStep and JsonQueryGalopAlignEdge.
const (
	JsonQueryGalopAlignOpToken = iota
	JsonQueryGalopAlignOpSet
	JsonQueryGalopAlignOpRule
	JsonQueryGalopAlignOpChoose
	JsonQueryGalopAlignOpLoop
	JsonQueryGalopAlignOpEps
)

// JsonQueryGalopAlignEdge is one transition of an JsonQueryGalopAlignNFA: on nothing (JsonQueryGalopAlignOpEps), or on a
// child that is the token, in the token set or of the rule it names, which
// it then stores under label.
type JsonQueryGalopAlignEdge struct {
	to    int32
	op    uint8
	sym   int32
	label uint8
	set   []int32
}

// JsonQueryGalopAlignNFA is a kind's alternatives as an automaton from state 0 to accept;
// each state's edges are in the order ANTLR prefers them (the lower
// alternative first).
type JsonQueryGalopAlignNFA struct {
	edges  [][]JsonQueryGalopAlignEdge
	accept int32
}

// JsonQueryGalopAlignNewNFA builds the automaton of steps.
func JsonQueryGalopAlignNewNFA(steps []JsonQueryGalopAlignStep) *JsonQueryGalopAlignNFA {
	a := &JsonQueryGalopAlignNFA{}
	a.accept = a.seq(steps, a.state())
	return a
}

func (a *JsonQueryGalopAlignNFA) state() int32 {
	a.edges = append(a.edges, nil)
	return int32(len(a.edges) - 1)
}

func (a *JsonQueryGalopAlignNFA) eps(from, to int32) {
	a.edges[from] = append(a.edges[from], JsonQueryGalopAlignEdge{to: to, op: JsonQueryGalopAlignOpEps})
}

// seq adds steps from state from on and returns the state they end in.
func (a *JsonQueryGalopAlignNFA) seq(steps []JsonQueryGalopAlignStep, from int32) int32 {
	for i := range steps {
		from = a.step(&steps[i], from)
	}
	return from
}

func (a *JsonQueryGalopAlignNFA) step(s *JsonQueryGalopAlignStep, from int32) int32 {
	switch s.op {
	case JsonQueryGalopAlignOpChoose:
		out := a.state()
		if s.exit == 0 {
			a.eps(from, out)
		}
		for _, alt := range s.alts {
			in := a.state()
			a.eps(from, in)
			a.eps(a.seq(alt, in), out)
		}
		if s.exit == 1 {
			a.eps(from, out)
		}
		return out
	case JsonQueryGalopAlignOpLoop:
		decide, out, body := a.state(), a.state(), a.state()
		a.eps(a.seq(s.alts[0], body), decide)
		if s.plus {
			a.eps(from, body)
		} else {
			a.eps(from, decide)
		}
		if s.cont {
			a.eps(decide, body)
			a.eps(decide, out)
		} else {
			a.eps(decide, out)
			a.eps(decide, body)
		}
		return out
	}
	to := a.state()
	a.edges[from] = append(a.edges[from], JsonQueryGalopAlignEdge{to: to, op: s.op, sym: s.sym, label: s.label, set: s.set})
	return to
}

// The bits of JsonQueryGalopStateLabel: the label's number (as the native parser
// numbers a rule's labels, from 1; a node's Label is a uint8) and whether it
// collects a list.
const (
	JsonQueryGalopLabelNumber = 255
	JsonQueryGalopLabelList   = 255 + 1
)

// parse walks the ATN from the start of rule, as errorsSource's run does,
// recovering from errors as ANTLR does, and returns the root node.
func (r *JsonQueryGalopRecovery) parse(rule int) int32 {
	e := &r.e
	p := e.p
	p.pos = 0
	p.stack = p.stack[:0]
	e.precs = e.precs[:0]
	r.enter(int32(rule), -1)
	s := JsonQueryGalopRuleStartState[rule]
	// back says the walk just left a loop back, which synced already: a
	// loop's next iteration does not sync at its start.
	back := false
	var root int32
	for {
		fromBack := back
		back = false
		if JsonQueryGalopStateIsStop[s] {
			// The end of a rule function checks for an error.
			if s, root = r.leave(); root >= 0 {
				return root
			}
			continue
		}
		if d := int(JsonQueryGalopStateDecision[s]); d >= 0 {
			// ANTLR matches the alternatives of a set decision as one set.
			if after := JsonQueryGalopDecisionSetAfter[d]; after >= 0 {
				r.state = s
				if e.ll1Alt(d) > 0 {
					r.reportMatch()
					r.take(false)
				} else {
					r.recoverInline(s, after, false)
				}
				s = after
				continue
			}
			alt, ok := r.decide(d, s, fromBack)
			if !ok {
				if s, root = r.leave(); root >= 0 {
					return root
				}
				continue
			}
			if k := JsonQueryGalopOuterAltStart[d]; k >= 0 {
				r.enterOuterAlt(JsonQueryGalopOuterAlt[int(k)+alt-1])
			}
			back = JsonQueryGalopDecisionKind[d] == JsonQueryGalopDecisionPlus && alt == int(JsonQueryGalopDecisionLoopAlt[d])
			s = JsonQueryGalopTransTarget[JsonQueryGalopTransStart[s]+int32(alt)-1]
			continue
		}
		// The generated code checks for an error after these Syncs.
		checked := false
		switch JsonQueryGalopStateSync[s] {
		case JsonQueryGalopSyncLoopBack:
			r.state = s
			r.sync(s, false)
			back, checked = true, true
		case JsonQueryGalopSyncBlockStart:
			if !fromBack {
				r.state = s
				r.sync(s, true)
				checked = true
			}
		}
		if checked && e.pending != nil {
			if s, root = r.leave(); root >= 0 {
				return root
			}
			continue
		}
		// An alternative of a left-recursive rule starts by changing the
		// rule's context.
		if len(JsonQueryGalopStateContext) > 0 {
			if c, ok := JsonQueryGalopStateContext[s]; ok {
				r.contextStep(c)
			}
		}
		i := JsonQueryGalopTransStart[s]
		t := JsonQueryGalopTransTarget[i]
		switch JsonQueryGalopTransKind[i] {
		case JsonQueryGalopKindEpsilon:
		case JsonQueryGalopKindRule:
			r.state = s
			p.stack = append(p.stack, JsonQueryGalopTransArg[i])
			if JsonQueryGalopMaxPrec > 0 {
				e.precs = append(e.precs, JsonQueryGalopStateCallPrec[s])
			}
			r.enter(JsonQueryGalopStateRule[t], s)
		case JsonQueryGalopKindPrec:
			// The generated code checks precpred and goes to its error exit.
			if level := JsonQueryGalopTransArg[i]; level < e.prec() {
				r.state = s
				r.pend(e.failedPredicate(s, level))
				if s, root = r.leave(); root >= 0 {
					return root
				}
				continue
			}
		case JsonQueryGalopKindAtom:
			r.state = s
			r.matchToken(s, t, p.la(1) == JsonQueryGalopTransArg[i], true)
			// The generated code checks for an error after a token match.
			if e.pending != nil {
				if s, root = r.leave(); root >= 0 {
					return root
				}
				continue
			}
		default:
			r.state = s
			if JsonQueryGalopStateWildcard[s] {
				r.matchToken(s, t, p.la(1) != JsonQueryEOF, false)
			} else {
				r.matchSet(s, i, t)
			}
		}
		s = t
	}
}

// decide makes decision d at state s as ANTLR's generated code does (see
// JsonQueryGalopEmu.decide), and reports false where that code goes to its error exit.
func (r *JsonQueryGalopRecovery) decide(d int, s int32, fromBack bool) (int, bool) {
	e := &r.e
	pos := e.p.pos
	kind := JsonQueryGalopDecisionKind[d]
	// A star loop's next iteration decides at its loop back's state.
	if !(kind == JsonQueryGalopDecisionStar && fromBack) {
		r.state = s
	}
	ll1 := JsonQueryGalopDecisionLL1[d]
	// A token an alternative accepts passes Sync too.
	if ll1 && e.pending == nil {
		if alt := e.ll1Alt(d); alt > 0 {
			return alt, true
		}
	}
	switch kind {
	case JsonQueryGalopDecisionAlt:
		r.sync(s, true)
		if e.pending != nil {
			return 0, false
		}
	case JsonQueryGalopDecisionOpt:
		// Adaptive prediction follows Sync with no error check.
		r.sync(s, true)
		if ll1 && e.pending != nil {
			return 0, false
		}
	case JsonQueryGalopDecisionStar:
		if !fromBack {
			r.sync(s, true)
			if e.pending != nil {
				return 0, false
			}
		}
	case JsonQueryGalopDecisionPlus:
		r.sync(s, false)
		if ll1 && e.pending != nil {
			return 0, false
		}
	}
	if !ll1 {
		alt, err := e.predict(d)
		if err != nil {
			r.pend(err)
			return 0, false
		}
		return alt, true
	}
	if alt := e.ll1Alt(d); alt > 0 {
		return alt, true
	}
	// An LL(1) choice fails; an optional block or a loop exits.
	if kind == JsonQueryGalopDecisionAlt {
		r.pend(e.noViable(pos, pos))
		return 0, false
	}
	return int(JsonQueryGalopAltLookStart[d+1] - JsonQueryGalopAltLookStart[d]), true
}

// read is the furthest token ANTLR's parse has read so far: the current one
// (consuming a token reads the next) or one prediction or single-token
// deletion looked ahead to.
func (r *JsonQueryGalopRecovery) read() int {
	p := r.e.p
	return min(max(p.pos, p.peek), len(p.types)-1)
}

// reportMatch is ANTLR's ReportMatch: a token matched, so error recovery ends.
func (r *JsonQueryGalopRecovery) reportMatch() {
	r.recovering = false
	r.lastIndex = -1
	r.lastStates = r.lastStates[:0]
}

// recoverInline is ANTLR's RecoverInline at match state s, whose transition
// leads to next (see JsonQueryGalopEmu.inlineFix). It returns the token single-token
// deletion consumes (the one after the current), or what single-token
// insertion returns (see missing), or -1 for a mismatch, which it leaves
// pending.
func (r *JsonQueryGalopRecovery) recoverInline(s, next int32, add bool) int32 {
	switch fix, exp, err := r.e.inlineFix(s, next); fix {
	case JsonQueryGalopFixDelete:
		r.deleteOne(err)
		return r.take(false)
	case JsonQueryGalopFixInsert:
		r.report(err)
		return r.missing(exp, add)
	default:
		r.pend(err)
	}
	return -1
}

// deleteOne is ANTLR's single-token deletion: the current token is reported
// with err and skipped as an error token.
func (r *JsonQueryGalopRecovery) deleteOne(err *JsonQueryGalopEmuError) {
	r.report(err)
	r.take(true)
	r.reportMatch()
}

// matchToken is ANTLR's Match (match set) or MatchWildcard at state s, whose
// transition leads to next, where ok says the current token matches. Match
// returns nil, adding no conjured token, while an error is pending, as after
// a failed set match; MatchWildcard does not check.
func (r *JsonQueryGalopRecovery) matchToken(s, next int32, ok, match bool) {
	if ok {
		r.reportMatch()
		r.label(s, r.take(false))
		return
	}
	if match && r.e.pending != nil {
		r.recoverInline(s, next, false)
		r.label(s, -1)
		return
	}
	r.label(s, r.recoverInline(s, next, true))
}

// matchSet is the generated code's match of the set at state s, whose
// transition i leads to next. Its label gets the current token, or what
// RecoverInline returns, and a list label appends that once (ANTLR assigns
// an implicit label first and appends its final value); a conjured token is
// not added to the tree.
func (r *JsonQueryGalopRecovery) matchSet(s, i, next int32) {
	tok := int32(r.e.p.pos)
	if JsonQueryGalopMatches(i, r.e.p.la(1)) {
		r.reportMatch()
		r.take(false)
	} else {
		tok = r.recoverInline(s, next, false)
	}
	r.label(s, tok)
}

// types are the types in x, ascending, EOF first.
func (x *JsonQueryGalopExpected) types() []int32 {
	var out []int32
	for i, ok := range x.in {
		if ok {
			out = append(out, int32(i-1))
		}
	}
	return out
}

// first is ANTLR's IntervalSet.first(): the smallest type in x, EOF first,
// or 0 for an empty set.
func (x *JsonQueryGalopExpected) first() int32 {
	for i, ok := range x.in {
		if ok {
			return int32(i - 1)
		}
	}
	return 0
}

// sync is ANTLR's Sync at state s, a block start or a loop back. It does
// nothing in error recovery mode or where the current token can follow s.
// At a block start it deletes one token when the token after it can follow,
// and otherwise leaves a mismatch pending; at a loop back it reports the
// token and skips to what can follow s or a rule being parsed.
func (r *JsonQueryGalopRecovery) sync(s int32, blockStart bool) {
	if r.recovering {
		return
	}
	switch fix, exp, err := r.e.syncFix(s, blockStart); fix {
	case JsonQueryGalopFixSkip:
		r.report(err)
		r.recoverySet(exp)
		r.consumeUntil(exp)
	case JsonQueryGalopFixDelete:
		r.deleteOne(err)
	case JsonQueryGalopFixMismatch:
		r.pend(err)
	}
}

// leave ends the rule being parsed as the end of its generated function
// does: a pending error is reported and recovered from (errorExit), and the
// rule returns (see exit).
func (r *JsonQueryGalopRecovery) leave() (int32, int32) {
	if r.e.pending != nil {
		r.errorExit()
	}
	follow, root := r.exit()
	if JsonQueryGalopMaxPrec > 0 {
		r.e.precs = r.e.precs[:len(r.e.p.stack)]
	}
	return follow, root
}

// contextStep is what an alternative of a left-recursive rule does to the
// rule's context at its start (JsonQueryGalopStateContext's encoding): an op
// alternative's PushNewRecursionContext, or a labeled primary one's new
// context, which keeps none of the children the rule had, as enterOuterAlt.
func (r *JsonQueryGalopRecovery) contextStep(c uint32) {
	alt := uint8(c & JsonQueryGalopContextAlt)
	if c&JsonQueryGalopContextPush == 0 {
		r.enterOuterAlt(alt)
		return
	}
	r.recursionStart(alt, uint16(c>>JsonQueryGalopContextLeftShift))
}

// errorExit reports the pending error and recovers as ANTLR's Recover does:
// a second error at the same token and state first skips that token, then
// the input is skipped to a token that can follow a rule being parsed.
func (r *JsonQueryGalopRecovery) errorExit() {
	e := &r.e
	p := e.p
	r.reportPending(e.pending)
	e.pending = nil
	if r.lastIndex == p.pos && slices.Contains(r.lastStates, r.state) {
		r.take(r.recovering)
	}
	r.lastIndex = p.pos
	r.lastStates = append(r.lastStates, r.state)
	set := JsonQueryGalopNewExpected()
	r.recoverySet(set)
	r.consumeUntil(set)
}

// recoverySet adds ANTLR's error recovery set to x: what can follow each
// rule being parsed but the entry rule.
func (r *JsonQueryGalopRecovery) recoverySet(x *JsonQueryGalopExpected) {
	for _, f := range r.e.p.stack {
		x.add(JsonQueryGalopTokenSets[JsonQueryGalopStateNext[f]])
	}
}

// consumeUntil skips tokens until one in set, or EOF.
func (r *JsonQueryGalopRecovery) consumeUntil(set *JsonQueryGalopExpected) {
	p := r.e.p
	for t := p.la(1); t != JsonQueryEOF && !set.has(t); t = p.la(1) {
		r.take(r.recovering)
	}
}
